arguments.command:
cat > tests/forms_test.sh <<'EOF'
#!/bin/bash
fail=0
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
# Cirrus function URL only allows [A-Za-z0-9_.-] in query keys (docs/platform/cirrus-functions.md)
for p in event seats refund; do
  [ -f app/forms/$p.form ] || continue
  bash bin/render $p | grep -o 'action="[^"]*"' | grep -q '?[A-Za-z0-9_.-]*[=">]' && ! bash bin/render $p | grep -o 'action="[^"]*"' | grep -q '?/' || { echo "render key $p"; fail=1; }
done
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
exit $fail
EOF
ls app/forms; bash scripts/verify.sh; echo $?

